// ---------------------------------------------------------------------------
// The sample set of the demo page.
//
// THIS DOCUMENT IS SYNTHETIC. It is generated by the code below, for the demo
// page only. It was never saved by Live, it contains no audio, and it contains
// no third-party content: every track, scene, clip and file name is invented.
// The wav files it references do not exist anywhere.
//
// It is NOT a complete Live set and is not meant to be opened in Live. It has
// the parts this library reads and rewrites, in the shapes the library's own
// regexes and unit-test fixtures use, and nothing else. Its job is to give
// every view of the demo something real to do:
//
//   - a Live 12 header, 8 tracks, 12 scenes and 61 session clips;
//   - scenes with structured tempo and time signature (4/4, 3/4, 6/8), one
//     name with an ampersand and one with a double quote;
//   - five planted problems, one per repair tool (see `buildSampleSet`);
//   - a damaged variant for the validation view (see `buildDamagedSampleSet`).
//
// Pure and deterministic: no clock, no randomness, no DOM, no I/O.
// ---------------------------------------------------------------------------

import { describeClipSlotLists, escapeXml } from "../../src/index.js"

export const SAMPLE_FILE_NAME = "Demo Set.als"
export const DAMAGED_FILE_NAME = "Damaged Set.als"

/** The invented library root every sample but one lives under. */
export const SAMPLE_LIBRARY_ROOT = "/Volumes/Demo SSD/Library"

// ---------------------------------------------------------------------------
// A tiny indented XML writer
// ---------------------------------------------------------------------------

type XmlNode =
  | string
  | { readonly open: string; readonly children: readonly XmlNode[] }

function element(open: string, children: readonly XmlNode[]): XmlNode {
  return { open, children }
}

/** `<Tag Value="..." />`, with the value escaped once. */
function value(tag: string, content: string | number | boolean): string {
  return `<${tag} Value="${escapeXml(String(content))}" />`
}

function serialize(node: XmlNode, depth: number, lines: string[]): void {
  const indent = "\t".repeat(depth)
  if (typeof node === "string") {
    lines.push(indent + node)
    return
  }
  const tag = node.open.split(" ")[0] ?? node.open
  lines.push(`${indent}<${node.open}>`)
  for (const child of node.children) serialize(child, depth + 1, lines)
  lines.push(`${indent}</${tag}>`)
}

// ---------------------------------------------------------------------------
// The set, as data
// ---------------------------------------------------------------------------

/** The tempo the set runs at. The stems below were warped at half of it. */
const MASTER_BPM = 120
/** Planted problem (b): the BPM most audio clips are warped at. */
const STEM_WARP_BPM = 60
/** The click clips had their warp fixed by hand; their loop windows were not. */
const CLICK_WARP_BPM = 120

const SAMPLE_RATE = 48_000
/** The allocator sits above every Id in the document. */
const NEXT_POINTEE_ID = 2200

type Meter = { readonly num: number; readonly den: number }

const FOUR_FOUR: Meter = { num: 4, den: 4 }
const THREE_FOUR: Meter = { num: 3, den: 4 }
const SIX_EIGHT: Meter = { num: 6, den: 8 }

/** Live 11+ encoding: `id = 99 * log2(den) + (num - 1)`. */
function timeSignatureId(meter: Meter): number {
  return 99 * Math.log2(meter.den) + (meter.num - 1)
}

type SceneSpec = {
  readonly name: string
  /** Palette index, or -1 for "no color". */
  readonly color: number
  /** The scene's own tempo; `null` leaves `IsTempoEnabled` false. */
  readonly tempo: number | null
  readonly meter: Meter
  /** Does the scene program the meter, or just inherit it? */
  readonly meterEnabled: boolean
  /**
   * Length of the section in beats, in the scale the stems were warped in
   * (half tempo, so half the real beat count). 0 = no stem plays here.
   */
  readonly beats: number
  /** One letter per track, in track order; `.` is an empty slot. */
  readonly clips: string
}

const SCENES: readonly SceneSpec[] = [
  { name: "COUNT IN", color: -1, tempo: 120, meter: FOUR_FOUR, meterEnabled: true, beats: 0, clips: "C......." },
  { name: "INTRO", color: 8, tempo: null, meter: FOUR_FOUR, meterEnabled: false, beats: 16, clips: "CD.K.P.S" },
  { name: "VERSE 1", color: -1, tempo: null, meter: FOUR_FOUR, meterEnabled: false, beats: 32, clips: "CDB...V." },
  { name: "PRE CHORUS", color: -1, tempo: null, meter: FOUR_FOUR, meterEnabled: false, beats: 8, clips: "CDBKG..." },
  { name: "CHORUS", color: 14, tempo: null, meter: FOUR_FOUR, meterEnabled: false, beats: 16, clips: "CDBKGPVS" },
  // The ampersand is stored escaped, as every text in the file is.
  { name: "VERSE 2 & BUILD", color: -1, tempo: null, meter: FOUR_FOUR, meterEnabled: false, beats: 24, clips: "CDB.G.V." },
  { name: "CHORUS 2", color: 14, tempo: null, meter: FOUR_FOUR, meterEnabled: false, beats: 16, clips: "CDBKGPVS" },
  { name: "BRIDGE", color: 64, tempo: 90, meter: SIX_EIGHT, meterEnabled: true, beats: 12, clips: "CD..GPV." },
  // A double quote in the value makes the attribute single-quoted.
  { name: 'INTERLUDE "B"', color: 38, tempo: 120, meter: FOUR_FOUR, meterEnabled: true, beats: 16, clips: "CD.KG..S" },
  { name: "BREAKDOWN", color: 50, tempo: null, meter: THREE_FOUR, meterEnabled: true, beats: 12, clips: "C..K.PV." },
  { name: "LAST CHORUS", color: 14, tempo: null, meter: FOUR_FOUR, meterEnabled: true, beats: 32, clips: "CDBKG.VS" },
  { name: "OUTRO", color: -1, tempo: 96.5, meter: FOUR_FOUR, meterEnabled: false, beats: 16, clips: "C..K.P.S" },
]

/** Where each section starts inside the stems, in the same half-tempo beats. */
const SECTION_STARTS: readonly number[] = SCENES.map((_, index) =>
  SCENES.slice(0, index).reduce((total, scene) => total + scene.beats, 0)
)

const STEM_BEATS = SCENES.reduce((total, scene) => total + scene.beats, 0)

type Routing = {
  readonly target: string
  readonly upper: string
  readonly lower: string
}

const TO_MAIN: Routing = { target: "AudioOut/Main", upper: "Master", lower: "" }

type TrackSpec = {
  readonly id: number
  readonly name: string
  readonly kind: "audio" | "midi"
  /** Palette index 0..69. */
  readonly color: number
  readonly output: Routing
  /** First Id of this track's automation and modulation targets. */
  readonly targetBase: number
  /** The stem this track plays, as a path inside the library. */
  readonly stem: string | null
}

const TRACKS: readonly TrackSpec[] = [
  {
    id: 8,
    name: "CLICK",
    kind: "audio",
    color: 27,
    output: { target: "AudioOut/External/S1", upper: "Ext. Out", lower: "3/4" },
    targetBase: 2000,
    stem: null,
  },
  { id: 9, name: "DRUMS", kind: "audio", color: 14, output: TO_MAIN, targetBase: 2010, stem: "Rhythm/drums_stem.wav" },
  { id: 10, name: "BASS", kind: "audio", color: 15, output: TO_MAIN, targetBase: 2020, stem: "Rhythm/bass_stem.wav" },
  { id: 11, name: "KEYS", kind: "audio", color: 3, output: TO_MAIN, targetBase: 2030, stem: "Keys & Pads/keys_stem.wav" },
  { id: 12, name: "GUITAR", kind: "audio", color: 19, output: TO_MAIN, targetBase: 2040, stem: "Guitars/guitar_stem.wav" },
  // Planted problem (a): this track reuses the target Ids of KEYS, the way a
  // track duplicated outside Live does.
  { id: 13, name: "PAD", kind: "audio", color: 21, output: TO_MAIN, targetBase: 2030, stem: "Keys & Pads/pad_stem.wav" },
  {
    id: 14,
    name: "LEAD VOX",
    kind: "audio",
    color: 68,
    output: TO_MAIN,
    targetBase: 2060,
    // Longer than 31 characters, so the alias record has to shorten it.
    stem: "Vocals/lead_vox_main_comp_tuned_and_edited_v3.wav",
  },
  { id: 15, name: "SYNTH", kind: "midi", color: 66, output: TO_MAIN, targetBase: 2070, stem: null },
]

const MASTER_TARGET_BASE = 2100

const CLICK = 0
const DRUMS = 1
const KEYS = 3
const GUITAR = 4
const PAD = 5
const LEAD_VOX = 6

/** The one audio file that lives outside the library root. */
const LOOSE_FILE = "/Volumes/Other Disk/Loose/extra.wav"
const LOOSE_FILE_SCENE = 9
const LOOSE_FILE_SAMPLE_RATE = 44_100

/** Planted problem (d): GUITAR sits two beats late in these scenes. */
const GUITAR_LATE_SCENES: ReadonlySet<number> = new Set([3, 4, 5, 6, 7])
const GUITAR_LATE_BY = 2

/** Planted problem (c): rows added later, still with Live's defaults. */
const UNSYNCED_SCENES: ReadonlySet<number> = new Set([9, 10, 11])
/** Planted problem (c): a section that was shortened, its timer never updated. */
const STALE_TIMER_SCENE = 5
const STALE_TIMER = 32

/** Planted problem (e): the one clip that uses the "Jump" follow action. */
const JUMP_SCENE = 8
const JUMP_TRACK = KEYS
const FOLLOW_NEXT = 4
const FOLLOW_JUMP = 9

/** Scenes whose LEAD VOX clip carries a volume fade drawn on the clip. */
const FADE_SCENES: ReadonlySet<number> = new Set([2, 9])

/**
 * The clip shade per scene. The palette is 5 rows of 14 columns: a clip keeps
 * its track's column (the hue) and moves this many rows down (the shade).
 */
const SCENE_SHADES: readonly number[] = [0, 0, 1, 2, 3, 1, 3, 4, 2, 1, 3, 0]

function clipColor(track: TrackSpec, sceneIndex: number): number {
  const column = track.color % 14
  const row = Math.floor(track.color / 14)
  return ((row + (SCENE_SHADES[sceneIndex] ?? 0)) % 5) * 14 + column
}

// ---------------------------------------------------------------------------
// Samples
// ---------------------------------------------------------------------------

type SampleFile = {
  readonly path: string
  readonly frames: number
  readonly sampleRate: number
}

/** Invented but stable: 24-bit stereo plus a 44-byte header. */
function fileSize(frames: number): number {
  return frames * 6 + 44
}

/** Invented but stable: a 16-bit sum over the path. It checks nothing. */
function fileCrc(path: string): number {
  let sum = 0
  for (const character of path) {
    sum = (sum * 31 + (character.codePointAt(0) ?? 0)) % 65_536
  }
  return sum
}

/** The path as the set file sees it, from `<root>/Sets/`. */
function relativePath(absolutePath: string): string {
  const prefix = `${SAMPLE_LIBRARY_ROOT}/`
  return absolutePath.startsWith(prefix)
    ? `../${absolutePath.slice(prefix.length)}`
    : `../../..${absolutePath.slice("/Volumes".length)}`
}

/** The v12 shape: one absolute `<Path>`, no `<Name>`, no alias `<Data>`. */
function sampleRef(file: SampleFile): XmlNode {
  return element("SampleRef", [
    element("FileRef", [
      value("RelativePathType", 1),
      value("RelativePath", relativePath(file.path)),
      value("Path", file.path),
      value("Type", 2),
      value("LivePackName", ""),
      value("LivePackId", ""),
      value("OriginalFileSize", fileSize(file.frames)),
      value("OriginalCrc", fileCrc(file.path)),
      value("SourceHint", ""),
    ]),
    value("DefaultDuration", file.frames),
    value("DefaultSampleRate", file.sampleRate),
  ])
}

function stemFile(track: TrackSpec, sceneIndex: number): SampleFile {
  if (track === TRACKS[PAD] && sceneIndex === LOOSE_FILE_SCENE) {
    // One second of audio per beat at 60 BPM.
    const seconds = SCENES[sceneIndex]?.beats ?? 0
    return {
      path: LOOSE_FILE,
      frames: seconds * LOOSE_FILE_SAMPLE_RATE,
      sampleRate: LOOSE_FILE_SAMPLE_RATE,
    }
  }
  return {
    path: `${SAMPLE_LIBRARY_ROOT}/${track.stem ?? ""}`,
    frames: STEM_BEATS * SAMPLE_RATE,
    sampleRate: SAMPLE_RATE,
  }
}

function clickFile(meter: Meter): SampleFile {
  const name =
    meter === FOUR_FOUR
      ? "click_4-4_one_bar.wav"
      : meter === SIX_EIGHT
        ? "click_6-8_one_bar.wav"
        : "click_3-4_one_bar.wav"
  return {
    path: `${SAMPLE_LIBRARY_ROOT}/Click/${name}`,
    frames: (meter === FOUR_FOUR ? 2 : 1.5) * SAMPLE_RATE,
    sampleRate: SAMPLE_RATE,
  }
}

// ---------------------------------------------------------------------------
// Clips
// ---------------------------------------------------------------------------

type FollowSpec = {
  readonly time: number
  readonly linked: boolean
  readonly enabled: boolean
  readonly action: number
  readonly jumpIndex: number
}

function followFor(trackIndex: number, sceneIndex: number): FollowSpec {
  const scene = SCENES[sceneIndex]
  const jump = sceneIndex === JUMP_SCENE && trackIndex === JUMP_TRACK
  const base = { action: jump ? FOLLOW_JUMP : FOLLOW_NEXT, jumpIndex: jump ? 7 : 1 }
  // A row with no stem only has the looping click: nothing to chain from, so
  // it keeps Live's defaults. So do the rows that were never synced.
  if (scene === undefined || scene.beats === 0 || UNSYNCED_SCENES.has(sceneIndex)) {
    return { ...base, time: 4, linked: true, enabled: false }
  }
  return {
    ...base,
    time: sceneIndex === STALE_TIMER_SCENE ? STALE_TIMER : scene.beats,
    linked: false,
    enabled: true,
  }
}

function followAction(follow: FollowSpec): XmlNode {
  return element("FollowAction", [
    value("FollowTime", follow.time),
    value("IsLinked", follow.linked),
    value("LoopIterations", 1),
    value("FollowActionA", follow.action),
    value("FollowActionB", 0),
    value("FollowChanceA", 100),
    value("FollowChanceB", 0),
    value("JumpIndexA", follow.jumpIndex),
    value("JumpIndexB", 1),
    value("FollowActionEnabled", follow.enabled),
  ])
}

function clipTimeSignature(meter: Meter): XmlNode {
  return element("TimeSignature", [
    element("TimeSignatures", [
      element('RemoteableTimeSignature Id="0"', [
        value("Numerator", meter.num),
        value("Denominator", meter.den),
      ]),
    ]),
  ])
}

/** A volume fade drawn on the clip, pointing at the track's own target. */
function clipEnvelopes(pointeeId: number | null): XmlNode {
  if (pointeeId === null) return element("Envelopes", ["<Envelopes />"])
  return element("Envelopes", [
    element("Envelopes", [
      element('ClipEnvelope Id="0"', [
        element("EnvelopeTarget", [value("PointeeId", pointeeId)]),
        element("Automation", [
          element("Events", [
            '<FloatEvent Id="1" Time="0" Value="0.5" />',
            '<FloatEvent Id="2" Time="2" Value="1" />',
          ]),
        ]),
      ]),
    ]),
  ])
}

type Window = {
  readonly start: number
  readonly end: number
  readonly loop: boolean
}

function clipHead(input: {
  readonly window: Window
  readonly name: string
  readonly color: number
  readonly meter: Meter
  readonly pointeeId: number | null
  readonly follow: FollowSpec
}): readonly XmlNode[] {
  return [
    value("CurrentStart", input.window.start),
    value("CurrentEnd", input.window.end),
    element("Loop", [
      value("LoopStart", input.window.start),
      value("LoopEnd", input.window.end),
      value("StartRelative", 0),
      value("LoopOn", input.window.loop),
      value("HiddenLoopStart", input.window.start),
      value("HiddenLoopEnd", input.window.end),
    ]),
    value("Name", input.name),
    value("Annotation", ""),
    value("Color", input.color),
    clipTimeSignature(input.meter),
    clipEnvelopes(input.pointeeId),
    followAction(input.follow),
  ]
}

function baseName(path: string): string {
  const file = path.split("/").pop() ?? path
  return file.replace(/\.wav$/, "")
}

function audioClip(trackIndex: number, sceneIndex: number): XmlNode {
  const track = TRACKS[trackIndex]!
  const scene = SCENES[sceneIndex]!
  const isClick = trackIndex === CLICK

  const file = isClick ? clickFile(scene.meter) : stemFile(track, sceneIndex)
  const isLoose = file.path === LOOSE_FILE
  const late =
    trackIndex === GUITAR && GUITAR_LATE_SCENES.has(sceneIndex)
      ? GUITAR_LATE_BY
      : 0
  const start = isClick || isLoose ? 0 : (SECTION_STARTS[sceneIndex] ?? 0) + late
  // The click loops over one bar, written in the same half-tempo scale.
  const length = isClick
    ? (scene.meter.num * 4) / scene.meter.den / 2
    : scene.beats
  const warpBpm = isClick ? CLICK_WARP_BPM : STEM_WARP_BPM

  return element('AudioClip Id="0" Time="0"', [
    ...clipHead({
      window: { start, end: start + length, loop: isClick },
      name: baseName(file.path),
      color: clipColor(track, sceneIndex),
      meter: scene.meter,
      pointeeId:
        trackIndex === LEAD_VOX && FADE_SCENES.has(sceneIndex)
          ? track.targetBase + 5
          : null,
      follow: followFor(trackIndex, sceneIndex),
    }),
    value("IsWarped", true),
    sampleRef(file),
    value("SampleVolume", 1),
    value("PitchCoarse", 0),
    value("PitchFine", 0),
    element("WarpMarkers", [
      '<WarpMarker Id="0" SecTime="0" BeatTime="0" />',
      `<WarpMarker Id="1" SecTime="${(60 / warpBpm) * 0.03125}" BeatTime="0.03125" />`,
    ]),
  ])
}

/** One bar of eighth notes. MIDI has no warp, so it is in real beats. */
function midiClip(trackIndex: number, sceneIndex: number): XmlNode {
  const track = TRACKS[trackIndex]!
  const scene = SCENES[sceneIndex]!
  const variant = sceneIndex % 2 === 0 ? "A" : "B"
  const notes = Array.from({ length: 8 }, (_, index) => {
    const velocity = index % 2 === 0 ? 100 : variant === "A" ? 72 : 84
    return `<MidiNoteEvent Time="${index * 0.5}" Duration="0.5" Velocity="${velocity}" OffVelocity="64" NoteId="${index + 1}" />`
  })

  return element('MidiClip Id="0" Time="0"', [
    ...clipHead({
      window: { start: 0, end: 4, loop: true },
      name: `synth pattern ${variant}`,
      color: clipColor(track, sceneIndex),
      meter: scene.meter,
      pointeeId: null,
      follow: followFor(trackIndex, sceneIndex),
    }),
    // Live 12 only: the converter has to take these out for Live 10.
    element("ScaleInformation", [value("Root", 0), value("Name", "Major")]),
    value("IsInKey", false),
    element("Notes", notes),
  ])
}

// ---------------------------------------------------------------------------
// Slots, tracks, scenes
// ---------------------------------------------------------------------------

/** The outer slot carries an inner, Id-less `<ClipSlot>`, as Live writes it. */
function clipSlot(id: number, clip: XmlNode | null): XmlNode {
  return element(`ClipSlot Id="${id}"`, [
    value("LomId", 0),
    element("ClipSlot", [clip === null ? "<Value />" : element("Value", [clip])]),
    value("HasStop", true),
  ])
}

function emptySlots(): readonly XmlNode[] {
  return SCENES.map((_, index) => clipSlot(index, null))
}

function target(tag: string, id: number): XmlNode {
  return element(`${tag} Id="${id}"`, [value("LockEnvelope", 0)])
}

function mixerParameter(
  tag: string,
  manual: string | number | boolean,
  firstId: number,
  withModulation: boolean
): XmlNode {
  return element(tag, [
    value("Manual", manual),
    target("AutomationTarget", firstId),
    ...(withModulation ? [target("ModulationTarget", firstId + 1)] : []),
  ])
}

function outputRouting(routing: Routing): XmlNode {
  return element("AudioOutputRouting", [
    value("Target", routing.target),
    value("UpperDisplayString", routing.upper),
    value("LowerDisplayString", routing.lower),
  ])
}

function track(trackIndex: number): XmlNode {
  const spec = TRACKS[trackIndex]!
  const tag = spec.kind === "audio" ? "AudioTrack" : "MidiTrack"

  const sessionSlots = SCENES.map((scene, sceneIndex) => {
    if (scene.clips[trackIndex] === "." || scene.clips[trackIndex] === undefined) {
      return clipSlot(sceneIndex, null)
    }
    return clipSlot(
      sceneIndex,
      spec.kind === "audio"
        ? audioClip(trackIndex, sceneIndex)
        : midiClip(trackIndex, sceneIndex)
    )
  })

  return element(`${tag} Id="${spec.id}"`, [
    value("LomId", 0),
    value("IsContentSelectedInDocument", false),
    value("PreferredContentViewMode", 0),
    element("TrackDelay", [value("Value", 0)]),
    element("Name", [
      value("EffectiveName", spec.name),
      value("UserName", spec.name),
    ]),
    value("Color", spec.color),
    // Live 12 only, and nested: the converter removes the whole block.
    element("TakeLanes", [
      element("TakeLanes", [
        element('TakeLane Id="0"', [value("LaneHeight", 68)]),
      ]),
      value("AreTakeLanesFolded", true),
    ]),
    value("LinkedTrackGroupId", -1),
    value("Freeze", false),
    value("NeedArrangerRefreeze", true),
    element("DeviceChain", [
      outputRouting(spec.output),
      element("Mixer", [
        value("LomId", 0),
        mixerParameter("Speaker", true, spec.targetBase, false),
        mixerParameter("Pan", 0, spec.targetBase + 1, true),
        mixerParameter("Volume", 1, spec.targetBase + 3, true),
      ]),
      element("MainSequencer", [
        value("LomId", 0),
        element("ClipSlotList", sessionSlots),
        ...(spec.kind === "audio"
          ? [target("VolumeModulationTarget", spec.targetBase + 5)]
          : []),
      ]),
      element("FreezeSequencer", [
        value("LomId", 0),
        element("ClipSlotList", emptySlots()),
      ]),
    ]),
  ])
}

/** The master, under the name Live 12 gives it. */
function mainTrack(): XmlNode {
  return element(
    'MainTrack SelectedToolPanel="7" SelectedTransformationName="" SelectedGeneratorName=""',
    [
      value("LomId", 0),
      element("Name", [value("EffectiveName", "Main"), value("UserName", "")]),
      value("Color", 40),
      element("DeviceChain", [
        outputRouting({
          target: "AudioOut/External/S0",
          upper: "Ext. Out",
          lower: "1/2",
        }),
        element("Mixer", [
          value("LomId", 0),
          mixerParameter("Volume", 1, MASTER_TARGET_BASE, true),
          mixerParameter("Tempo", MASTER_BPM, MASTER_TARGET_BASE + 2, true),
          mixerParameter(
            "TimeSignature",
            timeSignatureId(FOUR_FOUR),
            MASTER_TARGET_BASE + 4,
            false
          ),
        ]),
        // Live 12 writes one slot per scene here; Live 10 wants the list empty.
        element("FreezeSequencer", [
          value("LomId", 0),
          element("ClipSlotList", emptySlots()),
        ]),
      ]),
    ]
  )
}

function preHearTrack(): XmlNode {
  return element("PreHearTrack", [
    value("LomId", 0),
    element("Name", [value("EffectiveName", "0-Main"), value("UserName", "")]),
    value("Color", -1),
  ])
}

function scene(spec: SceneSpec, id: number): XmlNode {
  // Live switches to single quotes when the value holds a double quote, and
  // then leaves the double quote unescaped.
  const name = spec.name.includes('"')
    ? `<Name Value='${spec.name.replace(/&/g, "&amp;").replace(/</g, "&lt;")}' />`
    : value("Name", spec.name)

  return element(`Scene Id="${id}"`, [
    element("FollowAction", [
      value("FollowTime", 4),
      value("IsLinked", true),
      value("LoopIterations", 1),
      value("FollowActionA", FOLLOW_NEXT),
      value("FollowActionB", 0),
      value("FollowChanceA", 100),
      value("FollowChanceB", 0),
      value("JumpIndexA", 0),
      value("JumpIndexB", 0),
      value("FollowActionEnabled", false),
    ]),
    name,
    value("Annotation", ""),
    value("Color", spec.color),
    value("Tempo", spec.tempo ?? MASTER_BPM),
    value("IsTempoEnabled", spec.tempo !== null),
    value(
      "TimeSignatureId",
      timeSignatureId(spec.meterEnabled ? spec.meter : FOUR_FOUR)
    ),
    value("IsTimeSignatureEnabled", spec.meterEnabled),
    value("LomId", 0),
    '<ClipSlotsListWrapper LomId="0" />',
  ])
}

// ---------------------------------------------------------------------------
// The two documents
// ---------------------------------------------------------------------------

/**
 * The healthy sample: a Live 12 shaped set that passes `validateGeneratedSet`
 * with nothing to report, and still has work for every repair tool.
 *
 * Planted on purpose:
 *
 *   a. PAD reuses the six automation and modulation target Ids of KEYS.
 *   b. The stems are warped at 60 BPM while the set runs at 120, and the
 *      click clips had only their warp corrected.
 *   c. The last three rows have follow actions off, linked and timed at
 *      Live's default; "VERSE 2 & BUILD" has a stale timer.
 *   d. Five GUITAR clips sit two beats later than the DRUMS clips beside them.
 *   e. One clip (KEYS, in the interlude) uses the "Jump" follow action.
 *
 * One sample lives outside the library root, one file name is longer than 31
 * characters and one folder name holds an ampersand.
 */
export function buildSampleSet(): string {
  const document = element(
    'Ableton MajorVersion="5" MinorVersion="12.0_12402" SchemaChangeCount="5" Creator="Ableton Live 12.4.3" Revision="synthetic-demo-sample"',
    [
      element("LiveSet", [
        value("NextPointeeId", NEXT_POINTEE_ID),
        value("OverwriteProtectionNumber", 3076),
        value("LomId", 0),
        element(
          "Tracks",
          TRACKS.map((_, index) => track(index))
        ),
        mainTrack(),
        preHearTrack(),
        element(
          "Scenes",
          SCENES.map((spec, index) => scene(spec, index))
        ),
      ]),
    ]
  )

  const lines = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    "<!-- Synthetic sample for a demo page. Generated by code, never saved by Live. No audio, no third-party content. -->",
  ]
  serialize(document, 0, lines)
  return `${lines.join("\n")}\n`
}

/** Replaces the one occurrence of `search` found at or after `from`. */
function replaceAfter(
  xml: string,
  from: string,
  search: string,
  replacement: string
): string {
  const anchor = xml.indexOf(from)
  const at = anchor === -1 ? -1 : xml.indexOf(search, anchor)
  if (at === -1) {
    throw new Error(`sample damage could not be planted: "${search}" not found`)
  }
  return xml.slice(0, at) + replacement + xml.slice(at + search.length)
}

/**
 * The same set with structural damage planted, for the validation view. It
 * still parses, and `validateGeneratedSet` reports five problems across all
 * four rules:
 *
 *   - xml: DRUMS writes `NeedArrangerRefreeze` twice;
 *   - grid: BASS has 11 session slots for 12 scenes;
 *   - ids: `NextPointeeId` sits below the highest Id in the file;
 *   - ids: a LEAD VOX clip envelope points at a target that does not exist;
 *   - routing: GUITAR is routed into a track that does not exist.
 */
export function buildDamagedSampleSet(): string {
  let xml = buildSampleSet()

  const refreeze = '<NeedArrangerRefreeze Value="true" />'
  xml = replaceAfter(
    xml,
    '<EffectiveName Value="DRUMS" />',
    refreeze,
    `${refreeze}${refreeze}`
  )
  xml = replaceAfter(
    xml,
    '<EffectiveName Value="GUITAR" />',
    '<Target Value="AudioOut/Main" />',
    '<Target Value="AudioOut/Track.99/TrackIn" />'
  )
  xml = replaceAfter(
    xml,
    '<EffectiveName Value="LEAD VOX" />',
    `<PointeeId Value="${TRACKS[LEAD_VOX]!.targetBase + 5}" />`,
    '<PointeeId Value="4242" />'
  )
  xml = replaceAfter(
    xml,
    "<LiveSet>",
    `<NextPointeeId Value="${NEXT_POINTEE_ID}" />`,
    '<NextPointeeId Value="900" />'
  )

  // Last, the grid: BASS loses the slot of its final (empty) row.
  const bass = describeClipSlotLists(xml).find(
    (list) => list.trackName === "BASS" && list.isSession
  )
  const lastSlot = bass?.slots[bass.slots.length - 1]
  if (lastSlot === undefined) {
    throw new Error("sample damage could not be planted: BASS has no slots")
  }
  return xml.slice(0, lastSlot.start) + xml.slice(lastSlot.end)
}

// Kept in one place so the demo and its tests name the same two tracks.
export const SAMPLE_MIRROR_BASE = TRACKS[DRUMS]!.name
export const SAMPLE_MIRROR_TARGET = TRACKS[GUITAR]!.name
